/**
 * The contract between an engine and the platform, and the ONLY file an engine may import from outside its own folder.
 * For every job the platform builds an EngineContext and calls the engine's handler; the engine never sees Nest, TypeORM,
 * the HTTP layer or any other engine. Owned by the core team - engine developers do not edit this file.
 */
import 'reflect-metadata'
import { plainToInstance } from 'class-transformer'
import { validate, ValidationError } from 'class-validator'

export interface EngineLog {
  info(message: string, data?: Record<string, unknown>): void
  warn(message: string, data?: Record<string, unknown>): void
  error(message: string, data?: Record<string, unknown>): void
}

export interface HttpRequestOptions {
  headers?: Record<string, string>
  /** Default 15 000. */
  timeoutMs?: number
  /** Responses larger than this fail the request. Default 2 MB. */
  maxBytes?: number
}

export interface HttpResponse {
  status: number
  headers: Record<string, string>
  /** The body decoded as UTF-8 text. */
  body: string
  /** The URL that answered, after redirects. */
  url: string
  ms: number
}

/** Outbound HTTP. Only public http(s) addresses are reachable: internal and private networks are refused, redirects included. */
export interface EngineHttp {
  get(url: string, options?: HttpRequestOptions): Promise<HttpResponse>
  postJson(url: string, body: unknown, options?: HttpRequestOptions): Promise<HttpResponse>
}

export interface EngineQuery {
  /** Parameterised SQL ($1, $2, ...). Unqualified table names resolve to this engine's own schema; other schemas are refused. */
  query<T = Record<string, unknown>>(sql: string, params?: unknown[]): Promise<T[]>
}

export interface EngineDb extends EngineQuery {
  /** Runs several statements atomically: everything commits when the callback returns, rolls back when it throws. */
  tx<T>(work: (tx: EngineQuery) => Promise<T>): Promise<T>
}

export interface EngineContext {
  readonly jobId: string
  readonly jobType: string
  /** The project this job works on. Store it on every row the engine writes. */
  readonly projectId: string
  /** 1 for the first run, 2 for the first retry, ... Handlers must be safe to run again. */
  readonly attempt: number
  /** Aborted when the job is cancelled or times out. Pass it on / check it in long loops. */
  readonly signal: AbortSignal
  readonly log: EngineLog
  readonly http: EngineHttp
  readonly db: EngineDb
  /** Reports progress (0-100) to whoever watches the job. Cheap: calls are throttled. */
  progress(percent: number, note?: string): void
}

/** Throw it to fail a job on purpose. `retryable: false` skips the remaining retries (bad input, nothing to wait for). */
export class EngineError extends Error {
  constructor(
    message: string,
    readonly retryable = true
  ) {
    super(message)
    this.name = 'EngineError'
  }
}

export interface JobDefinition<TInput extends object, TOutput> {
  /** A class-validator class (like our DTOs). The platform validates the input against it before the job is queued. */
  input: new () => TInput
  /** Returns a JSON-serialisable result (at most 1 MB). Put anything large in the engine's own tables. */
  handler: (ctx: EngineContext, input: TInput) => Promise<TOutput>
  /** Hard limit for one attempt. Default 300 000 (5 min), maximum 3 600 000. */
  timeoutMs?: number
  /** Extra attempts after a failure. Default 2, maximum 10. */
  retries?: number
}

/** The type-erased shape stored in an engine. Build values with defineJob() to keep the handler typed. */
export interface RegisteredJob {
  input: new () => object
  handler: (ctx: EngineContext, input: never) => Promise<unknown>
  timeoutMs?: number
  retries?: number
}

export interface EngineDefinition {
  /** Lower-case letters, digits and underscores; also the name of the engine's Postgres schema and the prefix of its job types. */
  id: string
  /** How many jobs of this engine one worker process runs at once. Default 2, maximum 20. */
  concurrency?: number
  /** Job type (always `<id>.<name>`) -> definition. */
  jobs: Record<string, RegisteredJob>
}

export function defineJob<TInput extends object, TOutput>(job: JobDefinition<TInput, TOutput>): JobDefinition<TInput, TOutput> {
  return job
}

export function defineEngine(engine: EngineDefinition): EngineDefinition {
  return engine
}

export type InputCheck = { ok: true; value: object } | { ok: false; errors: string[] }

const collectMessages = (errors: ValidationError[], parent = ''): string[] =>
  errors.flatMap((error) => {
    const path = parent ? `${parent}.${error.property}` : error.property
    const own = Object.values(error.constraints ?? {}).map((message) => (parent ? `${path}: ${message}` : message))
    return [...own, ...collectMessages(error.children ?? [], path)]
  })

/** The one input check used both by the platform (before queueing) and by testEngine(), so a test fails exactly like production would. */
export async function validateJobInput(inputClass: new () => object, raw: unknown): Promise<InputCheck> {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return { ok: false, errors: ['input must be an object'] }
  const instance = plainToInstance(inputClass, raw)
  const problems = await validate(instance, { whitelist: true, forbidNonWhitelisted: true })
  return problems.length > 0 ? { ok: false, errors: collectMessages(problems) } : { ok: true, value: instance }
}

export interface TestRun {
  result: unknown
  logs: Array<{ level: 'info' | 'warn' | 'error'; message: string; data?: Record<string, unknown> }>
  progress: Array<{ percent: number; note?: string }>
}

export interface TestOverrides {
  http?: Partial<EngineHttp>
  db?: Partial<EngineDb>
  projectId?: string
  attempt?: number
  signal?: AbortSignal
}

/**
 * Runs one job of an engine in-process with a fake context, so an engine can be developed and tested without the
 * API, the queue or a database. Network and database are unavailable unless you pass fakes in `overrides`.
 */
export async function testEngine(engine: EngineDefinition, jobType: string, input: unknown, overrides: TestOverrides = {}): Promise<TestRun> {
  const job = engine.jobs[jobType]
  if (!job) throw new Error(`Engine "${engine.id}" has no job type "${jobType}"`)
  const checked = await validateJobInput(job.input, input)
  if (!checked.ok) throw new Error(`Invalid input: ${checked.errors.join('; ')}`)

  const run: TestRun = { result: undefined, logs: [], progress: [] }
  const unavailable = (what: string) => () => Promise.reject(new Error(`${what} is not available in tests - pass a fake in the overrides argument`))
  const log = (level: 'info' | 'warn' | 'error') => (message: string, data?: Record<string, unknown>) => void run.logs.push({ level, message, data })

  const context: EngineContext = {
    jobId: '00000000-0000-7000-8000-00000000000a',
    jobType,
    projectId: overrides.projectId ?? '00000000-0000-7000-8000-000000000001',
    attempt: overrides.attempt ?? 1,
    signal: overrides.signal ?? new AbortController().signal,
    log: { info: log('info'), warn: log('warn'), error: log('error') },
    http: { get: unavailable('ctx.http.get'), postJson: unavailable('ctx.http.postJson'), ...overrides.http },
    db: { query: unavailable('ctx.db.query'), tx: unavailable('ctx.db.tx'), ...overrides.db },
    progress: (percent, note) => void run.progress.push({ percent, note }),
  }
  run.result = await job.handler(context, checked.value as never)
  return run
}
